/**
 * ESP-IDF NVS partition image generator (format version 2, unencrypted).
 *
 * A faithful port of `nvs_partition_gen.py` (esp-idf-nvs-partition-gen) so the
 * installer's browser can build the exact image `provision.py` would produce,
 * without Python. Byte-for-byte equality with the reference tool is enforced by
 * `test/nvs.test.ts` against golden images generated by the reference tool.
 */

const PAGE_SIZE = 4096;
const MAX_ENTRIES = 126;
const ENTRY_SIZE = 32;
const FIRST_ENTRY_OFFSET = 64;
const BITMAP_OFFSET = 32;
const CHUNK_ANY = 0xff;
const PAGE_ACTIVE = 0xfffffffe;
const PAGE_FULL = 0xfffffffc;
const VERSION2 = 0xfe;
const MAX_STRING_SIZE = 4000;
const MAX_KEY_LENGTH = 15;

export const NvsType = {
  U8: 0x01,
  I8: 0x11,
  U16: 0x02,
  I16: 0x12,
  U32: 0x04,
  I32: 0x14,
  U64: 0x08,
  I64: 0x18,
  SZ: 0x21,
  BLOB: 0x41,
  BLOB_DATA: 0x42,
  BLOB_IDX: 0x48,
} as const;

export type NvsPrimitiveEncoding = 'u8' | 'i8' | 'u16' | 'i16' | 'u32' | 'i32' | 'u64' | 'i64';

export type NvsEntry =
  | { type: 'namespace'; key: string }
  | { type: 'data'; key: string; encoding: NvsPrimitiveEncoding; value: number | bigint }
  | { type: 'data'; key: string; encoding: 'string'; value: string }
  | { type: 'data'; key: string; encoding: 'binary'; value: Uint8Array };

export class NvsError extends Error {}

// ---------------------------------------------------------------------------
// CRC32 with zlib semantics: zlib.crc32(data, 0xFFFFFFFF)
// ---------------------------------------------------------------------------
const CRC_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();

/** zlib-compatible crc32(data, prev). NVS always uses prev = 0xFFFFFFFF. */
export function zlibCrc32(data: Uint8Array, prev = 0xffffffff): number {
  let crc = (prev ^ 0xffffffff) >>> 0;
  for (let i = 0; i < data.length; i++) {
    crc = (CRC_TABLE[(crc ^ data[i]!) & 0xff]! ^ (crc >>> 8)) >>> 0;
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function writeU32(buf: Uint8Array, off: number, v: number) {
  new DataView(buf.buffer, buf.byteOffset, buf.byteLength).setUint32(off, v >>> 0, true);
}
function writeU16(buf: Uint8Array, off: number, v: number) {
  new DataView(buf.buffer, buf.byteOffset, buf.byteLength).setUint16(off, v, true);
}

function entryCrc(entry: Uint8Array): number {
  const d = new Uint8Array(28);
  d.set(entry.subarray(0, 4), 0);
  d.set(entry.subarray(8, 32), 4);
  return zlibCrc32(d);
}

class PageFullError extends Error {}

class Page {
  entryNum = 0;
  readonly buf = new Uint8Array(PAGE_SIZE).fill(0xff);
  private readonly bitmap = new Uint8Array(32).fill(0xff);

  constructor(pageNum: number, empty: boolean) {
    if (!empty) this.setHeader(pageNum);
  }

  private setHeader(pageNum: number) {
    const h = new Uint8Array(32).fill(0xff);
    writeU32(h, 0, PAGE_ACTIVE);
    writeU32(h, 4, pageNum);
    h[8] = VERSION2;
    writeU32(h, 28, zlibCrc32(h.subarray(4, 28)));
    this.buf.set(h, 0);
  }

  get state(): number {
    return new DataView(this.buf.buffer).getUint32(0, true);
  }
  markFull() {
    writeU32(this.buf, 0, PAGE_FULL);
  }

  private writeBitmap() {
    const bitnum = this.entryNum * 2;
    const byteIdx = bitnum >> 3;
    const bitOffset = bitnum & 7;
    this.bitmap[byteIdx] = this.bitmap[byteIdx]! & ~(1 << bitOffset) & 0xff;
    this.buf.set(this.bitmap, BITMAP_OFFSET);
  }

  writeEntryToBuf(data: Uint8Array, entryCount: number) {
    const off = FIRST_ENTRY_OFFSET + ENTRY_SIZE * this.entryNum;
    this.buf.set(data, off);
    for (let i = 0; i < entryCount; i++) {
      this.writeBitmap();
      this.entryNum++;
    }
  }
}

function encodeKey(key: string): Uint8Array {
  const bytes = new TextEncoder().encode(key);
  if (bytes.length > MAX_KEY_LENGTH) throw new NvsError(`NVS key "${key}" exceeds ${MAX_KEY_LENGTH} bytes`);
  const out = new Uint8Array(16);
  out.set(bytes);
  return out;
}

export class NvsImage {
  private sizeLeft: number | null;
  private pageNum = -1;
  private readonly pages: Page[] = [];
  private cur!: Page;
  private namespaceCount = 0;
  private readonly writtenNamespaces = new Map<string, number>();
  private closed = false;

  /** @param partitionSize total partition size in bytes (multiple of 4096, >= 0x3000) */
  constructor(private readonly partitionSize: number) {
    if (partitionSize % PAGE_SIZE !== 0) throw new NvsError('NVS partition size must be a multiple of 4096');
    if (partitionSize < 3 * PAGE_SIZE) throw new NvsError('NVS partition must be at least 0x3000 bytes');
    // One page is reserved (left erased) for NVS garbage collection.
    this.sizeLeft = partitionSize - PAGE_SIZE;
    this.cur = this.createPage(false, false);
  }

  private createPage(isReserved: boolean, isEmpty: boolean): Page {
    if (this.pages.length && !isEmpty && this.cur.state === PAGE_ACTIVE) this.cur.markFull();
    if (this.sizeLeft === 0) throw new NvsError('NVS data does not fit in the partition');
    if (!isReserved && this.sizeLeft !== null) this.sizeLeft -= PAGE_SIZE;
    this.pageNum++;
    const page = new Page(this.pageNum, isEmpty || isReserved);
    this.pages.push(page);
    this.cur = page;
    return page;
  }

  private newPageForOverflow(): Page {
    return this.createPage(false, false);
  }

  private nsIndex(): number {
    return this.namespaceCount;
  }

  writeNamespace(name: string) {
    this.assertOpen();
    const existing = this.writtenNamespaces.get(name);
    if (existing) {
      // Matches reference behaviour: switching back to an existing namespace
      // only changes the current index (entries use namespace_count though).
      return;
    }
    this.namespaceCount++;
    const idx = this.namespaceCount;
    try {
      this.writePrimitive(name, idx, 'u8', 0);
    } catch (e) {
      if (!(e instanceof PageFullError)) throw e;
      this.newPageForOverflow();
      this.writePrimitive(name, idx, 'u8', 0);
    }
    this.writtenNamespaces.set(name, idx);
  }

  writeEntry(entry: NvsEntry) {
    this.assertOpen();
    if (entry.type === 'namespace') {
      this.writeNamespace(entry.key);
      return;
    }
    if (this.namespaceCount === 0) throw new NvsError('write a namespace entry before data entries');
    const ns = this.nsIndex();
    const run = () => {
      if (entry.encoding === 'string') {
        const bytes = new TextEncoder().encode(entry.value + '\0');
        this.writeVarlen(entry.key, bytes, 'string', ns);
      } else if (entry.encoding === 'binary') {
        this.writeVarlen(entry.key, entry.value, 'binary', ns);
      } else {
        this.writePrimitive(entry.key, entry.value, entry.encoding, ns);
      }
    };
    try {
      run();
    } catch (e) {
      if (!(e instanceof PageFullError)) throw e;
      this.newPageForOverflow();
      run();
    }
  }

  private writePrimitive(key: string, value: number | bigint, enc: NvsPrimitiveEncoding, ns: number) {
    const page = this.cur;
    if (page.entryNum >= MAX_ENTRIES) throw new PageFullError();
    const e = new Uint8Array(32).fill(0xff);
    e[0] = ns;
    e[2] = 0x01;
    e[3] = CHUNK_ANY;
    e.set(encodeKey(key), 8);
    const dv = new DataView(e.buffer);
    const n = typeof value === 'bigint' ? value : BigInt(Math.trunc(value));
    const range = (lo: bigint, hi: bigint) => {
      if (n < lo || n > hi) throw new NvsError(`value ${n} out of range for ${enc} key "${key}"`);
    };
    switch (enc) {
      case 'u8': range(0n, 0xffn); e[1] = NvsType.U8; dv.setUint8(24, Number(n)); break;
      case 'i8': range(-0x80n, 0x7fn); e[1] = NvsType.I8; dv.setInt8(24, Number(n)); break;
      case 'u16': range(0n, 0xffffn); e[1] = NvsType.U16; dv.setUint16(24, Number(n), true); break;
      case 'i16': range(-0x8000n, 0x7fffn); e[1] = NvsType.I16; dv.setInt16(24, Number(n), true); break;
      case 'u32': range(0n, 0xffffffffn); e[1] = NvsType.U32; dv.setUint32(24, Number(n), true); break;
      case 'i32': range(-0x80000000n, 0x7fffffffn); e[1] = NvsType.I32; dv.setInt32(24, Number(n), true); break;
      case 'u64': range(0n, 0xffffffffffffffffn); e[1] = NvsType.U64; dv.setBigUint64(24, n, true); break;
      case 'i64': range(-(2n ** 63n), 2n ** 63n - 1n); e[1] = NvsType.I64; dv.setBigInt64(24, n, true); break;
    }
    writeU32(e, 4, entryCrc(e));
    page.writeEntryToBuf(e, 1);
  }

  private writeVarlen(key: string, data: Uint8Array, enc: 'string' | 'binary', ns: number) {
    const page = this.cur;
    const datalen = data.length;
    if (enc === 'string' && datalen > MAX_STRING_SIZE) {
      throw new NvsError(`string for key "${key}" exceeds ${MAX_STRING_SIZE} bytes`);
    }
    const dataEntryCount = ((datalen + 31) & ~31) / 32;
    const totalEntryCount = dataEntryCount + 1;
    if (page.entryNum >= MAX_ENTRIES) throw new PageFullError();
    if (page.entryNum + totalEntryCount >= MAX_ENTRIES && enc === 'string') throw new PageFullError();

    const e = new Uint8Array(32).fill(0xff);
    e[0] = ns;
    if (enc === 'string') e[2] = dataEntryCount + 1;
    e[3] = CHUNK_ANY;
    e.set(encodeKey(key), 8);
    e[1] = enc === 'string' ? NvsType.SZ : NvsType.BLOB;

    if (enc === 'binary') {
      this.writeBlobV2(e, data);
    } else {
      writeU16(e, 24, datalen);
      writeU32(e, 28, zlibCrc32(data));
      writeU32(e, 4, entryCrc(e));
      page.writeEntryToBuf(e, 1);
      page.writeEntryToBuf(data, dataEntryCount);
    }
  }

  private writeBlobV2(e: Uint8Array, data: Uint8Array) {
    const chunkStart = 0;
    let chunkCount = 0;
    let offset = 0;
    let remaining = data.length;
    let page = this.cur;
    for (;;) {
      const tailroom = (MAX_ENTRIES - page.entryNum - 1) * ENTRY_SIZE;
      if (tailroom < 0) throw new NvsError('NVS page overflow');
      const chunkSize = tailroom < remaining ? tailroom : remaining;
      remaining -= chunkSize;
      e[1] = NvsType.BLOB_DATA;
      const chunkEntries = ((chunkSize + 31) & ~31) / 32;
      e[2] = chunkEntries + 1;
      e[3] = chunkStart + chunkCount;
      const chunk = data.subarray(offset, offset + chunkSize);
      writeU16(e, 24, chunkSize);
      writeU32(e, 28, zlibCrc32(chunk));
      writeU32(e, 4, entryCrc(e));
      page.writeEntryToBuf(e, 1);
      page.writeEntryToBuf(chunk, chunkEntries);
      chunkCount++;
      if (remaining || tailroom - chunkSize < ENTRY_SIZE) {
        page = this.newPageForOverflow();
      }
      offset += chunkSize;
      if (!remaining) {
        e.fill(0xff, 24, 32);
        e[1] = NvsType.BLOB_IDX;
        e[2] = 1;
        e[3] = CHUNK_ANY;
        writeU32(e, 24, data.length);
        e[28] = chunkCount;
        e[29] = chunkStart;
        writeU32(e, 4, entryCrc(e));
        page.writeEntryToBuf(e, 1);
        return;
      }
    }
  }

  private assertOpen() {
    if (this.closed) throw new NvsError('NVS image already finalised');
  }

  /** Finalise: pad with erased pages (+ reserved page) and return the image. */
  finish(): Uint8Array {
    if (!this.closed) {
      for (;;) {
        try {
          this.createPage(false, true);
        } catch (e) {
          if (!(e instanceof NvsError)) throw e;
          this.sizeLeft = null;
          this.createPage(true, true);
          break;
        }
      }
      this.closed = true;
    }
    const out = new Uint8Array(this.pages.length * PAGE_SIZE);
    this.pages.forEach((p, i) => out.set(p.buf, i * PAGE_SIZE));
    if (out.length !== this.partitionSize) {
      throw new NvsError(`internal: image size ${out.length} != partition size ${this.partitionSize}`);
    }
    return out;
  }
}

/** Build an NVS image from an ordered entry list (same semantics as the CSV input). */
export function generateNvsImage(entries: readonly NvsEntry[], partitionSize: number): Uint8Array {
  const img = new NvsImage(partitionSize);
  for (const e of entries) img.writeEntry(e);
  return img.finish();
}
